from pathlib import Path
import subprocess,json,base64,html
r=Path(__file__).resolve().parent;info=json.loads((r/'render-info.json').read_text());plan=json.loads((r/'storyboard.json').read_text());words=json.loads((r/'words.json').read_text())
subprocess.run(['ffmpeg','-v','error','-y','-i',str(r/'render.mp4'),'-i',str(r/'assets/narration.wav'),'-map','0:v:0','-map','1:a:0','-c:v','copy','-af','loudnorm=I=-18:TP=-2:LRA=7,apad','-t',str(info['duration']),'-c:a','aac','-b:a','192k','-movflags','+faststart',str(r/'practice.mp4')],check=True)
d=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_format','-show_streams','-of','json',str(r/'practice.mp4')]));v=next(s for s in d['streams'] if s['codec_type']=='video');assert(v['width'],v['height'],v['r_frame_rate'])==(1920,1080,'30/1');assert abs(float(d['format']['duration'])-info['duration'])<.05;assert any(s['codec_type']=='audio' for s in d['streams']);subprocess.run(['ffmpeg','-v','error','-i',str(r/'practice.mp4'),'-f','null','-'],check=True)
(r/'verification.json').write_text(json.dumps({'duration':float(d['format']['duration']),'resolution':[1920,1080],'fps':30,'decode':'passed','audio':'original uploaded source narration, normalized; no voice generation','captions':'ASR word-aligned; not manually frame-certified'},indent=2))
uri='data:video/mp4;base64,'+base64.b64encode((r/'practice.mp4').read_bytes()).decode();rows=''.join(f'<button data-beat="{i}" data-time="{b["start"]}"><small>{b["start"]:.1f}s</small> {html.escape(b["teaching_job"])}</button>' for i,b in enumerate(plan['beats']));transcript=' '.join(f'<span data-word="{i}">{html.escape(w["w"])}</span>' for i,w in enumerate(words))
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transcript-first practice — Databricks</title><style>*{box-sizing:border-box}body{margin:0;background:#10191f;color:#eaf1f4;font:16px/1.6 system-ui}main{max-width:1400px;padding:28px;margin:auto}h1{font-size:clamp(28px,4vw,46px);line-height:1.15}h2{font-size:21px}p{color:#b9c9d1}.player{display:grid;grid-template-columns:minmax(0,2fr) minmax(280px,1fr);gap:22px;align-items:start}video{width:100%;background:#000;border-radius:13px}.why{background:#1b3038;border:1px solid #49616c;border-radius:12px;padding:20px;min-height:290px}.why small{color:#e9bd7a;text-transform:uppercase;letter-spacing:.1em}.why h2{line-height:1.3}.why p{font-size:15px}nav{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0}button{font:inherit;background:#1b3038;color:#eaf1f4;border:1px solid #49616c;border-radius:7px;padding:9px 13px;cursor:pointer;text-align:left}button.active{border-color:#eac282;background:#3e392e}button small{color:#e9bd7a;margin-right:6px}.transcript{max-width:1100px;line-height:2}.transcript span.active{color:#fff;background:#7b5428;border-radius:3px}.note{font-size:13px;border-top:1px solid #38505b;padding-top:18px}a{color:#a9dfd4}@media(max-width:900px){.player{grid-template-columns:1fr}.why{min-height:0}}</style><main><p>REELFACTORY / TRANSCRIPT-FIRST PRACTICE</p><h1>One transcript → eight teaching beats</h1><p>Original Databricks wording and narration · 46 seconds · static fictional presenter placeholder · reference-matched graphics study</p><div class="player"><video controls playsinline preload="metadata" src="'''+uri+'''"></video><aside class="why"><small id="beat">Teaching beat</small><h2 id="job"></h2><p id="spoken"></p><small>What the graphic does</small><p id="visual"></p><small>Why</small><p id="why"></p></aside></div><nav>'''+rows+'''</nav><details><summary>Original spoken transcript</summary><p class="transcript">'''+transcript+'''</p></details><p class="note">Practice source: <a href="https://www.youtube.com/watch?v=HtR5m5VjaDQ">Databricks Genie Ontology Explained</a>, uploaded reference part00, approximately 00:37.33–01:23.70. Narration is the original source audio, not generated or cloned. The static fictional presenter is a placeholder, not the source speaker. Product claims are preserved from that passage; this exercise does not independently verify current availability. Graphics are illustrative and do not show actual product execution. Glyphs and timing are not certified exact matches to the source. Local study only; nothing has been published.</p></main><script>const beats='''+json.dumps(plan['beats'])+''',words='''+json.dumps(words)+''';const v=document.querySelector('video');let active=-1;function update(){const t=v.currentTime;let i=beats.findIndex(b=>t>=b.start&&t<b.end);if(i<0)i=t<beats[0].start?0:beats.length-1;if(i!==active){active=i;const b=beats[i];document.querySelector('#beat').textContent='Beat '+(i+1)+' / '+b.start.toFixed(1)+'–'+b.end.toFixed(1)+'s';document.querySelector('#job').textContent=b.teaching_job;document.querySelector('#spoken').textContent=b.spoken_summary;document.querySelector('#visual').textContent=b.visual;document.querySelector('#why').textContent=b.why;document.querySelectorAll('[data-beat]').forEach(e=>e.classList.toggle('active',+e.dataset.beat===i))}document.querySelectorAll('[data-word]').forEach(e=>{const w=words[+e.dataset.word];e.classList.toggle('active',t>=w.s&&t<w.e)})}v.addEventListener('timeupdate',update);document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{v.currentTime=+b.dataset.time;update();v.play().catch(()=>{})});update();</script>'''
(r/'review.html').write_text(page);print('Finished practice video and explanation-linked review player')
